// Short, authored lessons selected by question ID, never by course-wide fallback.
import {renderGrammarText} from './grammar-terms.js';
const lesson=(title,rule,forms,example,caution)=>({title,rule,forms,example:{fr:example[0],ko:example[1]},caution});
export const miniLessons = {
  vouloir:lesson('veux는 vouloir가 바뀐 형태예요','“원하다”의 기본형은 vouloir예요. 주어에 맞춰 바꾼 뒤 원하는 행동을 동사원형으로 붙여요.',
    [['je / tu','veux'],['il / elle','veut'],['nous','voulons'],['vous','voulez'],['ils / elles','veulent']],['Tu veux manger.','너는 먹고 싶어.'],'Je veut가 아니라 Je veux예요. 뒤의 manger는 주어에 맞춰 바꾸지 않아요.'),
  dormir:lesson('dormir와 dors는 언제 쓰나요?','dormir는 “자다”라는 기본형이에요. veux 뒤에는 원형을 쓰지만, “나는 잔다”에서는 dors로 바꿔요.',
    [['기본형','dormir'],['나는 잔다','Je dors.'],['나는 자고 싶다','Je veux dormir.']],['Je ne veux pas dormir.','나는 자고 싶지 않아.'],'Je veux dors처럼 두 동사를 모두 주어에 맞춰 바꾸지 않아요.'),
  rester:lesson('rester ici를 한 덩어리로','rester는 “머무르다”, ici는 “여기”예요. Je veux 뒤에 rester ici를 붙이면 여기 있고 싶다는 뜻이에요.',
    [['머무르다','rester'],['여기 머무르다','rester ici'],['집에 머무르다','rester à la maison']],['Je veux rester à la maison.','나는 집에 있고 싶어.'],'ici 앞에 à를 붙이지 않아요. ici 자체에 “여기에”라는 뜻이 있어요.'),
  wantNegative:lesson('하고 싶지 않다: ne veux pas','ne와 pas로 활용된 동사 veux를 감싸요. 원하는 행동을 나타내는 동사원형은 pas 뒤에 와요.',
    [['하고 싶다','Je veux partir.'],['하고 싶지 않다','Je ne veux pas partir.'],['다른 행동으로','Je ne veux pas manger.']],['Je ne veux pas dormir.','나는 자고 싶지 않아.'],'Je veux ne partir pas가 아니에요. ne → veux → pas → partir 순서로 써요.'),
  continuer:lesson('continuer로 행동만 바꿔요','continuer는 “계속하다”예요. Je veux가 바람을, continuer가 원하는 행동을 나타내요.',
    [['계속하다','continuer'],['나는 계속한다','Je continue.'],['나는 계속하고 싶다','Je veux continuer.']],['Tu veux continuer.','너는 계속하고 싶어.'],'veux 뒤에서는 continue가 아니라 원형 continuer를 써요.'),
  pouvoir:lesson('peux는 pouvoir의 현재형','“할 수 있다”는 pouvoir를 주어에 맞춰 바꿔요. 그 뒤에 할 수 있는 행동을 동사원형으로 넣어요.',
    [['je / tu','peux'],['il / elle','peut'],['nous','pouvons'],['vous','pouvez'],['ils / elles','peuvent']],['Tu peux parler.','너는 말할 수 있어.'],'veux는 “원하다”, peux는 “할 수 있다”예요. 마지막 x도 확인해요.'),
  attendre:lesson('attendre: 기다리다','attendre는 원형이고 j’attends는 “나는 기다린다”예요. peux 뒤에서는 attendre를 그대로 써요.',
    [['기본형','attendre'],['나는 기다린다','J’attends.'],['나는 기다릴 수 있다','Je peux attendre.']],['Je ne peux pas attendre.','나는 기다릴 수 없어.'],'attendre의 t는 두 개예요. Je peux attends라고 쓰지 않아요.'),
  essayer:lesson('essayer: 해보다, 시도하다','Je peux 뒤에 essayer를 붙이면 “해볼 수 있다”예요. 다른 행동을 넣어 가능 표현을 넓힐 수 있어요.',
    [['해보다','essayer'],['말하다','parler'],['기다리다','attendre']],['Je peux essayer.','나는 해볼 수 있어.'],'peux 뒤에 de나 à를 끼워 넣지 않아요: Je peux essayer.'),
  canNegative:lesson('할 수 없다: ne peux pas','ne … pas가 peux를 감싸면 가능하다는 뜻을 부정해요. 뒤의 행동은 동사원형으로 남아요.',
    [['올 수 있다','Je peux venir.'],['올 수 없다','Je ne peux pas venir.'],['말할 수 없다','Je ne peux pas parler.']],['Je ne peux pas attendre.','나는 기다릴 수 없어.'],'pas는 venir나 parler 뒤가 아니라 peux 바로 뒤에 놓아요.'),
  recommencer:lesson('recommencer: 다시 시작하다','commencer는 “시작하다”, recommencer는 “다시 시작하다”예요. 이 동사는 re-가 더해지며 뜻이 바뀌어요.',
    [['시작하다','commencer'],['다시 시작하다','recommencer'],['다시 시작할 수 있다','Je peux recommencer.']],['Je veux recommencer.','나는 다시 시작하고 싶어.'],'peux나 veux 뒤에서는 recommence가 아니라 recommencer를 써요.'),
  aimer:lesson('J’aime 뒤에 좋아하는 활동','aimer는 “좋아하다”예요. je와 쓰는 aime가 모음으로 시작해서 Je aime를 J’aime로 줄여요.',
    [['나는 좋아한다','J’aime.'],['너는 좋아한다','Tu aimes.'],['그녀는 좋아한다','Elle aime.'],['좋아하는 활동','J’aime cuisiner.']],['J’aime marcher.','나는 걷는 걸 좋아해.'],'J’aimes가 아니라 J’aime예요. 뒤의 활동 lire·cuisiner는 동사원형이에요.'),
  lire:lesson('lire는 원형, lis는 현재형','“읽다”의 원형은 lire예요. J’aime 뒤에서는 좋아하는 활동 자체를 나타내므로 lire를 써요.',
    [['읽다','lire'],['나는 읽는다','Je lis.'],['나는 읽는 것을 좋아한다','J’aime lire.']],['J’aime lire ce livre.','나는 이 책 읽는 것을 좋아해.'],'J’aime lis라고 하지 않아요. aime만 주어 je에 맞춰 활용해요.'),
  beaucoup:lesson('beaucoup는 얼마나 좋아하는지','beaucoup는 “많이, 아주”예요. 이 문장에서는 aime 뒤, 활동을 나타내는 동사원형 앞에 놓아요.',
    [['좋아한다','J’aime marcher.'],['아주 좋아한다','J’aime beaucoup marcher.'],['다른 활동으로','J’aime beaucoup lire.']],['J’aime beaucoup cuisiner.','나는 요리하는 걸 아주 좋아해.'],'이 구조에서는 J’aime → beaucoup → 활동 순서로 기억해요.'),
  likeNegative:lesson('J’aime → Je n’aime pas','ne가 모음 앞에서 n’로 줄어요. n’가 aime 바로 앞에 오므로 주어는 J’가 아니라 Je로 돌아와요.',
    [['긍정','J’aime lire.'],['부정','Je n’aime pas lire.'],['다른 활동으로','Je n’aime pas cuisiner.']],['Je n’aime pas attendre.','나는 기다리는 걸 좋아하지 않아.'],'J’n’aime나 Je ne aime라고 쓰지 않아요. Je + n’aime + pas로 나눠 봐요.'),
  dessiner:lesson('dessiner로 좋아하는 활동 바꾸기','dessiner는 “그림을 그리다”예요. J’aime 뒤에 원형을 넣어 좋아하는 일을 말해요.',
    [['그림 그리다','dessiner'],['나는 그림을 그린다','Je dessine.'],['그림 그리기를 좋아한다','J’aime dessiner.']],['Tu aimes dessiner.','너는 그림 그리는 걸 좋아해.'],'J’aime와 Tu aimes를 비교해 보세요. 주어가 je에서 tu로 바뀌면 aime에 -s가 붙고, 뒤에 오는 dessiner는 그대로예요.'),
  etrePresent:lesson('suis는 être의 현재형','être는 “~이다, ~에 있다”예요. 주어 je에는 suis를 쓰고, 뒤에 상태나 장소를 붙여요.',
    [['je','suis'],['tu','es'],['il / elle','est'],['nous','sommes'],['vous','êtes'],['ils / elles','sont']],['Tu es ici.','너는 여기에 있어.'],'Je est가 아니라 Je suis예요. ai는 “가지고 있다”라는 다른 동사의 형태예요.'),
  homeLocation:lesson('집에 있다: être à la maison','à la maison은 “집에, 집에서”예요. suis 뒤에 붙이면 집에 있는 상태를 표현해요.',
    [['집','la maison'],['집에','à la maison'],['집에 있다','Je suis à la maison.']],['Elle est à la maison.','그녀는 집에 있어.'],'maison은 여성 명사예요. 이 표현에서는 au maison이 아니라 à la maison이에요.'),
  ici:lesson('ici는 관사 없이 써요','ici는 “여기(에)”라는 장소 부사예요. 물건 이름인 명사와 달리 un이나 le를 붙이지 않아요.',
    [['여기','ici'],['저기, 거기','là'],['여기에 있다','Je suis ici.']],['Je reste ici.','나는 여기 머물러.'],'ici 자체에 장소 뜻이 있으므로 à ici라고 하지 않아요.'),
  etreNegative:lesson('상태·장소를 부정하는 ne suis pas','ne … pas로 suis를 감싸요. 뒤의 장소 표현은 바꾸지 않아요.',
    [['긍정','Je suis ici.'],['부정','Je ne suis pas ici.'],['다른 장소','Je ne suis pas à la maison.']],['Elle n’est pas ici.','그녀는 여기에 있지 않아.'],'est처럼 모음으로 시작하면 ne가 n’가 돼요. suis 앞에서는 ne를 그대로 써요.'),
  pret:lesson('prêt와 prête: 준비된 사람에 맞춰요','prêt는 남성 단수, prête는 여성 단수예요. être 뒤의 형용사는 설명하는 사람의 성·수에 맞춰요.',
    [['남성 단수','prêt'],['여성 단수','prête'],['남성·혼성 복수','prêts'],['여성 복수','prêtes']],['Elle est prête.','그녀는 준비됐어.'],'여성형 e를 붙여도 ê는 유지해요. Je의 화자 성별에 따라 prêt 또는 prête를 써요.'),
  fatigue:lesson('fatigué와 fatiguée','“피곤한”은 fatigué예요. 여성 한 사람을 설명할 때 e, 여러 사람일 때 s를 더해요.',
    [['남성 단수','fatigué'],['여성 단수','fatiguée'],['남성·혼성 복수','fatigués'],['여성 복수','fatiguées']],['Elles sont fatiguées.','그녀들은 피곤해.'],'여성형은 fatiguée예요. é를 e로 바꾸는 것이 아니라 뒤에 e를 하나 더 붙여요.'),
  avoirPresent:lesson('J’ai와 avoir의 현재형','avoir는 “가지고 있다”예요. je와 쓰는 ai 앞에서는 Je가 J’로 줄어요.',
    [['je','ai → J’ai'],['tu','as'],['il / elle','a'],['nous','avons'],['vous','avez'],['ils / elles','ont']],['Tu as un livre.','너는 책 한 권이 있어.'],'Je ai가 아니라 J’ai예요. 단수 물건 하나 앞에는 명사의 성에 맞는 un·une를 써요.'),
  sac:lesson('sac은 남성 명사예요','물건 이름은 성과 함께 익히면 문장에서 관사를 고르기 쉬워요. sac은 “가방”이라는 남성 명사예요.',
    [['가방 하나','un sac'],['그 가방','le sac'],['가방 여러 개','des sacs']],['J’ai un sac.','나는 가방 하나가 있어.'],'복수에는 보통 s를 붙여 sacs로 써요. 단어만 묻는 문제의 답은 sac이에요.'),
  nounArticles:lesson('un·une는 명사의 성에 맞춰요','막 소개하는 물건 하나에는 un 또는 une를 써요. 사람의 성별이 아니라 뒤의 명사가 기준이에요.',
    [['남성 · 책','un livre'],['남성 · 가방','un sac'],['여성 · 질문','une question']],['J’ai une question.','나는 질문 하나가 있어.'],'question은 여성 명사예요. 말하는 사람이 남성이어도 une question이에요.'),
  negativeDe:lesson('하나도 없다: pas de','가진 물건이 없다고 부정할 때 un·une·des는 보통 de가 돼요. 동사 avoir는 ne … pas로 감싸요.',
    [['가방이 있다','J’ai un sac.'],['가방이 없다','Je n’ai pas de sac.'],['책이 없다','Je n’ai pas de livre.']],['Je n’ai pas de question.','나는 질문이 없어.'],'모든 부정문에서 관사가 de가 되는 것은 아니에요. être 뒤에서는 Ce n’est pas un sac처럼 un을 유지해요.'),
  faim:lesson('배고프다: avoir faim','프랑스어에서는 “배고픔을 가지고 있다”는 구조로 말해요. faim 앞에 관사를 넣지 않아요.',
    [['배고프다','avoir faim'],['나는 배고프다','J’ai faim.'],['너는 배고프다','Tu as faim.']],['Je n’ai pas faim.','나는 배고프지 않아.'],'Je suis faim이나 J’ai une faim이 아니라, 이 기본 표현은 J’ai faim이에요.'),
  soif:lesson('목마르다: avoir soif','soif는 “갈증”이에요. avoir soif를 한 표현으로 익히고 avoir만 주어에 맞춰 바꿔요.',
    [['목마르다','avoir soif'],['나는 목마르다','J’ai soif.'],['그녀는 목마르다','Elle a soif.']],['Je n’ai pas soif.','나는 목마르지 않아.'],'이 표현에서는 soif 앞에 관사를 넣지 않아요. 배고픔은 같은 구조의 avoir faim이에요.'),
  allerPresent:lesson('vais는 aller의 현재형','“가다”의 기본형은 aller지만 현재형은 불규칙하게 바뀌어요. je에는 vais를 써요.',
    [['je','vais'],['tu','vas'],['il / elle','va'],['nous','allons'],['vous','allez'],['ils / elles','vont']],['Je vais à Paris.','나는 파리에 가.'],'Je va가 아니라 Je vais예요. Paris 같은 도시 이름 앞에는 보통 à를 써요.'),
  maison:lesson('maison은 집, à la maison은 집에','maison은 여성 명사예요. 단어 자체와 장소 표현을 함께 익혀요.',
    [['집 한 채','une maison'],['집에','à la maison'],['집으로 간다','Je vais à la maison.']],['Je suis à la maison.','나는 집에 있어.'],'vais는 이동, suis는 위치를 말해요. à la maison은 둘 다에 쓸 수 있어요.'),
  aArticles:lesson('à le는 au, à la는 그대로','장소 앞의 à가 정관사와 만날 때 모양이 달라져요. 남성 le와 복수 les는 합쳐져요.',
    [['à + le café','au café'],['à + la gare','à la gare'],['à + l’hôtel','à l’hôtel'],['à + les toilettes','aux toilettes']],['Je vais au marché.','나는 시장에 가.'],'à le라고 따로 쓰지 않아요. 여성형 à la를 au로 바꾸지도 않아요.'),
  allerNegative:lesson('가지 않는다: ne vais pas','“나는 간다”의 vais를 ne … pas로 감싸요. à Paris 같은 목적지는 뒤에 남아요.',
    [['간다','Je vais à Paris.'],['가지 않는다','Je ne vais pas à Paris.'],['다른 목적지','Je ne vais pas au café.']],['Je ne vais pas à la gare.','나는 기차역에 가지 않아.'],'pas는 목적지 뒤가 아니라 vais 뒤에 놓아요.'),
  voudrais:lesson('voudrais: 부드럽게 부탁하는 형태','Je voudrais는 vouloir의 조건법 현재를 쓴 정중한 요청이에요. 여기서는 원하는 메뉴를 바로 뒤에 붙여요.',
    [['직접적인 바람','Je veux un café.'],['정중한 요청','Je voudrais un café.'],['부탁을 덧붙이기','Je voudrais un thé, s’il vous plaît.']],['Je voudrais un croissant.','크루아상 하나 주세요.'],'voudrais의 마지막 s를 유지해요. 주문 하나를 말할 때 un·une도 함께 넣어요.'),
  cafe:lesson('café: 커피와 카페','café는 남성 명사예요. 주문할 때 un café는 커피 한 잔, 장소를 말할 때 au café는 카페에서·카페에라는 뜻이에요.',
    [['커피 한 잔','un café'],['카페에','au café'],['커피 여러 잔','des cafés']],['Je voudrais un café.','커피 한 잔 주세요.'],'마지막 글자는 é예요. café는 커피와 카페 두 뜻을 문맥에 따라 가질 수 있어요.'),
  menuArticles:lesson('메뉴도 un·une와 함께','주문 한 개·한 잔을 말할 때 명사의 성에 따라 un 또는 une를 골라요.',
    [['남성','un café'],['남성','un thé'],['남성','un croissant'],['남성','un sandwich'],['여성','une salade']],['Je voudrais une salade.','샐러드 하나 주세요.'],'메뉴 이름의 끝 글자만 보고 성을 단정하지 말고 un croissant·une salade처럼 묶어서 익혀요.'),
  the:lesson('thé: 차 한 잔을 말해요','thé는 음료인 “차”라는 남성 명사예요. 한 잔을 주문할 때는 un thé, 양을 정하지 않고 차를 마신다고 할 때는 du thé를 써요.',
    [['차 한 잔','un thé'],['차를 마시다','boire du thé'],['주문하기','Je voudrais un thé.']],['Je bois du thé.','나는 차를 마셔.'],'thé의 h와 é를 모두 써요. te는 “너를·너에게”라는 다른 단어예요.'),
  besoin:lesson('avoir besoin de는 필요한 것을 이어요','avoir besoin de 뒤에 필요한 것의 이름을 붙여요. avoir만 주어에 맞춰 바꾸고 besoin de는 유지해요.',
    [['도움이 필요하다','avoir besoin d’aide'],['휴식이 필요하다','avoir besoin de repos'],['너는 휴식이 필요하다','Tu as besoin de repos.']],['J’ai besoin de repos.','나는 휴식이 필요해.'],'besoin 뒤의 de도 표현의 일부예요. 모음 앞에서는 de가 d’로 줄어요.'),
  aide:lesson('aide와 d’aide의 차이','aide는 “도움”이라는 여성 명사예요. besoin de 뒤에 오면 de aide가 d’aide로 줄어요.',
    [['도움','aide'],['de + aide','d’aide'],['도움이 필요하다','J’ai besoin d’aide.']],['Tu as besoin d’aide.','너는 도움이 필요해.'],'d’는 aide에 원래 붙은 글자가 아니에요. 앞의 전치사 de가 줄어든 형태예요.'),
  besoinNegative:lesson('필요하지 않다: n’ai pas besoin de','avoir를 ne … pas로 감싸요. besoin de는 그대로 남기고 필요한 것을 그 뒤에 놓아요.',
    [['긍정','J’ai besoin de repos.'],['부정','Je n’ai pas besoin de repos.'],['모음으로 시작하는 말','Je n’ai pas besoin d’aide.']],['Je n’ai pas besoin de dormir.','난 굳이 자지 않아도 돼.'],'pas는 besoin 뒤가 아니라 ai 뒤에 와요. 부정문이라고 de를 지우지 않아요.'),
  besoinAction:lesson('필요한 행동에는 de + 동사원형','필요한 것이 행동이면 besoin de 뒤에 dormir·manger 같은 원형을 넣어요.',
    [['좀 자야 한다','J’ai besoin de dormir.'],['뭐 좀 먹어야 한다','J’ai besoin de manger.'],['먹고 싶다','Je veux manger.']],['Tu as besoin de dormir.','넌 좀 자야 해.'],'“원한다”는 veux, “필요하다”는 ai besoin de예요. besoin 뒤에서는 de를 유지해요.'),
  whereSingular:lesson('한 장소를 물을 때 Où est','Où는 ‘어디’, est는 être의 3인칭 단수 현재형이에요. Où est 뒤에 찾는 장소를 넣어요.',
    [['여성 명사','Où est la gare ?'],['남성 명사','Où est le café ?'],['모음·무음 h 앞','Où est l’hôtel ?']],['Où est le musée ?','박물관은 어디에 있나요?'],'où는 위치를 묻는 말이고 ou는 “또는”이에요. ù의 악센트를 확인해요.'),
  gare:lesson('gare는 기차역이라는 여성 명사','gare는 보통 철도역을 가리켜요. la gare를 함께 익히면 장소를 묻거나 목적지를 말할 수 있어요.',
    [['기차역 하나','une gare'],['그 기차역','la gare'],['기차역에','à la gare']],['Où est la gare ?','기차역은 어디에 있나요?'],'la gare이므로 이동 표현도 au gare가 아니라 à la gare예요.'),
  toilettes:lesson('les toilettes는 복수 표현이에요','프랑스어에서 화장실을 가리키는 toilettes는 보통 복수로 써요. 관사는 les, 동사는 sont를 맞춰요.',
    [['단수 장소','Où est la gare ?'],['복수 장소','Où sont les toilettes ?'],['화장실에','aux toilettes']],['Les toilettes sont ici.','화장실은 여기에 있어요.'],'한국어로 한 곳을 말해도 les toilettes는 복수예요. Où est les toilettes라고 하지 않아요.'),
  hotel:lesson('무음 h 앞에서는 l’hôtel','hôtel은 남성 명사이고 h는 무음이에요. 정관사 le의 e를 줄여 l’hôtel로 연결해요.',
    [['호텔 하나','un hôtel'],['그 호텔','l’hôtel'],['호텔에','à l’hôtel']],['Où est l’hôtel ?','호텔은 어디에 있나요?'],'hôtel의 ô를 유지해요. 모든 h가 같은 것은 아니지만 hôtel의 h 앞에서는 줄임이 일어나요.'),
  musee:lesson('musée는 남성 명사예요','“박물관”은 musée예요. -ée로 끝나도 남성 명사이므로 le·un을 써요.',
    [['박물관 하나','un musée'],['그 박물관','le musée'],['박물관에','au musée']],['Où est le musée ?','박물관은 어디에 있나요?'],'끝이 e라고 모두 여성은 아니에요. musée는 le musée로 함께 외워요.')
};

Object.assign(miniLessons, {
  pcAvoir:lesson('복합과거: avoir 현재형 + 과거분사','복합과거는 avoir나 être의 현재형에 과거분사를 붙여 만들어요. 여기서 연습하는 travailler와 finir에는 avoir를 써요.',
    [['je → j’','ai travaillé'],['tu','as fini'],['il / elle','a travaillé'],['nous','avons travaillé'],['vous','avez fini'],['ils / elles','ont travaillé']],['Tu as fini ton travail.','너는 네 일을 끝냈어.'],'J’ai travailler가 아니라 J’ai travaillé예요. avoir가 복합과거의 조동사일 때는 뒤에 과거분사를 써요.'),
  pcEr:lesson('-er 동사는 -é로 바꿔요','regarder의 과거분사는 -er를 떼고 -é를 붙인 regardé예요. 이 규칙은 아래의 -er 동사들에 적용돼요.',
    [['regarder · 보다','regardé'],['travailler · 일하다','travaillé'],['manger · 먹다','mangé'],['parler · 말하다','parlé']],['Hier, j’ai regardé un film.','나는 어제 영화를 봤어.'],'regarde는 현재형, regarder는 원형, regardé는 과거분사예요. 마지막 é를 구분해요.'),
  pcIrregular:lesson('voir → vu: 불규칙 과거분사','voir의 과거분사는 vu예요. -er → -é 규칙으로 만들 수 없으므로 원형과 과거분사를 짝지어 익혀요.',
    [['voir · 보다','vu'],['avoir · 가지다','eu'],['être · ~이다','été'],['faire · 하다','fait'],['prendre · 취하다','pris'],['lire · 읽다','lu']],['J’ai vu ce film.','나는 이 영화를 봤어.'],'voir·vu·vois는 달라요: 원형 voir, 과거분사 vu, je의 현재형 vois예요. 과거 문장은 J’ai vu로 써요.'),
  pcFini:lesson('finir → fini: 끝낸 일을 말해요','finir의 과거분사는 fini예요. 이 동사는 -ir를 -i로 바꾸며, avoir 현재형과 함께 복합과거를 만들어요.',
    [['finir · 끝내다','fini'],['choisir · 고르다','choisi'],['réussir · 성공하다','réussi']],['J’ai fini mon travail.','나는 내 일을 끝냈어.'],'모든 -ir 동사에 같은 규칙을 쓰면 안 돼요. venir는 venu처럼 다른 형태예요.'),
  pcNegative:lesson('과거 부정문은 조동사를 감싸요','복합과거에서 ne … pas는 ai·as·avons 같은 조동사 앞뒤에 와요. 과거분사 vu는 pas 뒤에 남아요.',
    [['긍정','J’ai vu ce film.'],['부정','Je n’ai pas vu ce film.'],['nous로 바꾸면','Nous n’avons pas vu ce film.']],['Je n’ai pas fini mon travail.','나는 내 일을 끝내지 않았어.'],'Je n’ai vu pas가 아니에요. vu는 voir의 불규칙 과거분사이며 부정문에서도 vu를 써요.'),
  pcEncore:lesson('아직 안 했다: pas encore','pas encore는 “아직 ~하지 않았다”예요. 이 복합과거에서는 n’ai 뒤, 과거분사 mangé 앞에 놓아요.',
    [['먹었다','J’ai mangé.'],['먹지 않았다','Je n’ai pas mangé.'],['아직 먹지 않았다','Je n’ai pas encore mangé.']],['Je n’ai pas encore fini.','나는 아직 끝내지 않았어.'],'manger의 과거분사는 mangé예요. ne … pas가 ai를 감싸고 encore는 pas 뒤에 와요.'),
  pcVoir:lesson('주어가 바뀌어도 이 vu는 그대로','voir의 과거분사는 vu예요. 이 문장들은 목적어 ce film이 뒤에 있으므로 주어에 따라 avoir만 바꿔요.',
    [['나는 봤다','J’ai vu ce film.'],['너는 봤다','Tu as vu ce film.'],['우리는 봤다','Nous avons vu ce film.']],['Elle a vu ce film.','그녀는 이 영화를 봤어.'],'이 avoir 구문에서 주어가 여성·복수라고 vue·vus로 바꾸지 않아요. 앞에 놓인 직접목적어와의 일치는 별도 규칙이에요.'),
  pcMange:lesson('우리가 먹었다: nous avons mangé','manger는 과거분사 mangé가 돼요. “우리는 먹었다”는 nous에 맞춘 avons와 mangé를 연결해요.',
    [['나는 먹었다','J’ai mangé.'],['우리는 먹었다','Nous avons mangé.'],['장소 덧붙이기','Nous avons mangé au restaurant.']],['Hier, nous avons mangé au restaurant.','우리는 어제 식당에서 먹었어.'],'현재형 mangeons와 과거형 avons mangé를 구분해요. hier는 문장 앞이나 뒤에 둘 수 있어요.'),
  pcAlle:lesson('aller → allé, être와 성·수 일치','aller의 복합과거는 être와 과거분사 allé를 써요. 과거분사는 주어의 성과 수에 맞춰 바꿔요.',
    [['남성 단수','Il est allé.'],['여성 단수','Elle est allée.'],['남성·혼성 복수','Ils sont allés.'],['여성 복수','Elles sont allées.']],['Je suis allée à Paris.','나는 파리에 갔어. (여성 화자)'],'Je suis allé는 남성 화자, Je suis allée는 여성 화자예요. J’ai allé라고 하지 않아요.'),
  pcArrive:lesson('arriver → arrivé → arrivée','arriver의 과거분사는 arrivé예요. être와 함께 쓰고, 여성형에는 e, 복수형에는 s를 붙여요.',
    [['남성 단수','arrivé'],['여성 단수','arrivée'],['남성·혼성 복수','arrivés'],['여성 복수','arrivées']],['Elles sont arrivées à l’heure.','그녀들은 제시간에 도착했어.'],'여성형은 arrivé의 é 뒤에 e를 더한 arrivée예요. 조동사도 elle est·elles sont로 맞춰요.'),
  pcParti:lesson('partir → parti, 여성 복수는 parties','떠난 일을 말할 때 être + parti를 써요. parti를 기본으로 주어에 맞는 e·s를 붙여요.',
    [['남성 단수','Il est parti.'],['여성 단수','Elle est partie.'],['남성·혼성 복수','Ils sont partis.'],['여성 복수','Elles sont parties.']],['Elle est partie hier soir.','그녀는 어젯밤 떠났어.'],'partir의 과거분사는 parté가 아니라 parti예요. elles에는 여성·복수 표시를 모두 붙여 parties예요.'),
  pcEtreNegative:lesson('être를 쓰는 과거 부정문','ne … pas로 조동사 être를 감싸요. 뒤의 과거분사는 부정문에서도 주어의 성·수에 맞춰요.',
    [['긍정','Elle est allée à Paris.'],['부정','Elle n’est pas allée à Paris.'],['여성 복수','Elles ne sont pas allées à Paris.']],['Elle n’est pas partie.','그녀는 떠나지 않았어.'],'est 앞에서는 n’, sont 앞에서는 ne예요. 부정문이라고 allée·partie의 e를 빼지 않아요.'),
  imparfaitHabiter:lesson('habiter → habitais: 과거의 배경','반과거는 보통 현재형 nous에서 -ons를 뺀 어간에 어미를 붙여요. nous habitons → habit-에 je의 -ais를 붙여요.',
    [['je → j’','habitais'],['tu','habitais'],['il / elle','habitait'],['nous','habitions'],['vous','habitiez'],['ils / elles','habitaient']],['À cette époque, j’habitais à Paris.','나는 그때 파리에 살고 있었어.'],'반과거는 당시의 상태·습관·진행 중인 배경을 보여줘요. 단순히 오래 걸렸다는 이유만으로 고르지 않아요.'),
  imparfaitTravailler:lesson('nous의 반과거 어미는 -ions','현재형 nous travaillons에서 -ons를 빼면 travaill-이에요. 반과거 nous에는 -ions를 붙여 travaillions가 돼요.',
    [['현재 · 우리는 일한다','nous travaillons'],['반과거 어간','travaill-'],['반과거 · 우리는 일하곤 했다','nous travaillions'],['반과거 · 나는 일하곤 했다','je travaillais']],['Nous travaillions tous les jours.','우리는 매일 일하곤 했어.'],'travaillons와 travaillions를 구분해요. 반과거에는 -ions의 i가 들어가요.'),
  imparfaitEtre:lesson('être의 반과거는 ét-에서 시작해요','être는 nous sommes에서 어간을 만들지 않는 예외예요. ét-에 반과거 어미를 붙여요.',
    [['je → j’','étais'],['tu','étais'],['il / elle','était'],['nous','étions'],['vous','étiez'],['ils / elles','étaient']],['J’étais à la maison.','나는 집에 있었어.'],'être의 현재형 suis와 반과거 étais를 구분해요. ét-의 é도 유지해요.'),
  imparfaitLire:lesson('lire의 반과거: lisais','현재형 nous lisons에서 -ons를 빼면 lis-예요. je의 반과거 어미 -ais를 붙이면 lisais가 돼요.',
    [['원형','lire'],['현재 · 우리','nous lisons'],['반과거 · 나','je lisais'],['반과거 · 우리','nous lisions']],['Hier, à huit heures, je lisais.','어제 8시에 나는 읽고 있었어.'],'여기서는 그 시점에 진행 중이던 읽기를 보여줘요. “읽었다”라는 완료 사건은 j’ai lu로 표현할 수 있어요.'),
  backgroundEvent:lesson('진행 중인 배경과 새로 생긴 사건','~하는 중이었다는 배경은 반과거, 그때 생긴 사건은 복합과거로 연결해요. quand는 “~할 때”예요.',
    [['읽던 배경 · lisons → lis-','je lisais'],['요리하던 배경 · cuisinons → cuisin-','je cuisinais'],['자던 배경 · dormons → dorm-','je dormais'],['전화벨이 울린 사건','le téléphone a sonné']],['Je dormais quand le téléphone a sonné.','내가 자고 있을 때 전화가 울렸어.'],'je의 반과거 어미는 -ais예요. 전화의 주어 le téléphone은 단수라 a sonné를 써요.'),
  pastWeather:lesson('날씨와 상태를 반과거로','배경을 설명할 때 “비가 오고 있었다”는 il pleuvait, “집에 있었다”는 j’étais à la maison이에요.',
    [['현재 · 비가 온다','il pleut'],['반과거 · 비가 오고 있었다','il pleuvait'],['현재 · 나는 있다','je suis'],['반과거 · 나는 있었다','j’étais']],['Il pleuvait et j’étais à la maison.','비가 오고 있었고 나는 집에 있었어.'],'날씨를 나타내는 il은 특정 사람을 가리키지 않아요. et는 두 배경을 “그리고”로 연결해요.'),
  imparfaitAvoir:lesson('avoir의 반과거: avais·avions','현재형 nous avons에서 -ons를 뺀 av-에 반과거 어미를 붙여요. avoir du temps는 “시간이 있다”예요.',
    [['je → j’','avais'],['tu','avais'],['il / elle','avait'],['nous','avions'],['vous','aviez'],['ils / elles','avaient']],['À cette époque, tu avais du temps.','너는 그때 시간이 있었어.'],'현재형 tu as와 반과거 tu avais는 달라요. 어간은 avoir-가 아니라 av-예요.'),
  futureNegative:lesson('미래를 부정해도 동사는 한 덩어리','travaillerons는 travailler + nous의 미래 어미 -ons예요. 이 한 동사를 ne … pas로 감싸요.',
    [['현재','Nous travaillons.'],['미래','Nous travaillerons.'],['미래의 부정','Nous ne travaillerons pas.']],['Nous ne travaillerons pas demain.','우리는 내일 일하지 않을 거야.'],'복합과거와 달리 별도의 avoir·être를 넣지 않아요. ne → travaillerons → pas예요.'),
  siPresent:lesson('가능한 조건: si + 현재, 결과는 미래','앞으로 가능한 조건을 말할 때 이 si절에는 현재형을 써요. 조건이 맞으면 할 일은 단순미래로 이어줘요.',
    [['시간이 있으면 · 현재','Si j’ai le temps'],['갈 것이다 · 미래','j’irai'],['일할 것이다 · 미래','je travaillerai']],['Si j’ai le temps, je travaillerai.','시간이 있으면 나는 일할 거야.'],'미래 이야기여도 이 si절에는 j’aurai를 쓰지 않아요. J’irai si j’ai le temps처럼 순서를 바꿀 수 있어요.'),
  siRain:lesson('비가 오면: si + il → s’il','pleuvoir의 현재형은 il pleut예요. 조건의 si가 il 앞에서 s’로 줄어 S’il pleut가 돼요.',
    [['비가 온다','Il pleut.'],['비가 오면','S’il pleut'],['머무를 것이다','nous resterons'],['외출하지 않을 것이다','je ne sortirai pas']],['S’il pleut, nous resterons à la maison.','비가 오면 우리는 집에 있을 거야.'],'조건절에는 pleuvra가 아니라 현재형 pleut를 써요. resterons·sortirai는 결과절의 미래형이에요.'),
  siVenir:lesson('네가 오면: si tu viens','venir의 tu 현재형은 viens예요. 조건절에는 viens, 앞으로 할 결과에는 미래형을 써요.',
    [['오다 · 원형','venir'],['네가 오면 · 현재','si tu viens'],['함께 먹을 것이다 · 미래','nous mangerons ensemble']],['Si tu viens, nous mangerons ensemble.','네가 오면 우리는 함께 먹을 거야.'],'viens와 미래형 viendras를 구분해요. 이 si절에서는 Si tu viendras라고 하지 않아요.'),
  siWeather:lesson('날씨가 좋으면: s’il fait beau','il fait beau는 좋은 날씨를 말하는 고정 표현이에요. si와 연결하면 S’il fait beau가 돼요.',
    [['날씨가 좋다','Il fait beau.'],['날씨가 좋으면','S’il fait beau'],['우리는 걸을 것이다','nous marcherons']],['S’il fait beau, nous marcherons.','날씨가 좋으면 우리는 걸을 거야.'],'marcher의 미래형은 marcher + -ons예요. 조건의 fait를 미래형 fera로 바꾸지 않아요.'),
  siImagined:lesson('상상하는 조건: avais·avions','현재와 다른 상황을 가정할 때 si 뒤에는 반과거를 써요. 그 결과는 조건법 현재로 이어줘요.',
    [['내게 시간이 있다면','Si j’avais le temps'],['우리에게 시간이 있다면','Si nous avions le temps'],['나는 여행할 텐데','je voyagerais'],['우리는 더 읽을 텐데','nous lirions plus']],['Si j’avais le temps, je voyagerais.','시간이 있다면 나는 여행할 텐데.'],'조건절에 aurais·aurions를 쓰지 않아요. avoir의 반과거 avais·avions와 결과의 조건법을 구분해요.'),
  siEtais:lesson('내가 ~라면: si j’étais','être의 반과거 étais로 상상하는 상황을 말해요. Si j’étais toi는 “내가 너라면”이라는 조언의 시작이에요.',
    [['내가 부자라면','Si j’étais riche'],['내가 너라면','Si j’étais toi'],['나는 머물 텐데','je resterais ici'],['나는 여행할 텐데','je voyagerais']],['Si j’étais toi, je resterais ici.','내가 너라면 여기 머물 텐데.'],'조건의 j’étais와 결과의 조건법 resterais를 구분해요. Si je serais toi라고 쓰지 않아요.'),
  directObject:lesson('목적어를 le·la·les로 바꾸기','“무엇을?”에 해당하는 직접목적어를 대명사로 받아요. 명사의 성·수에 맞추고 활용된 동사 앞에 놓아요.',
    [['le livre · 그 책','Je le lis.'],['la lettre · 그 편지','Je la lis.'],['les livres · 그 책들','Je les lis.'],['les lettres · 그 편지들','Je les lis.']],['Je lis la lettre. → Je la lis.','나는 그 편지를 읽어. → 나는 그것을 읽어.'],'lui는 “그에게·그녀에게”라는 간접목적어예요. 이 문제의 “그것을”에는 le·la·les를 써요.'),
  objectInfinitive:lesson('어느 동사의 목적어인지 먼저 봐요','veux·peux 뒤에 동사원형이 올 때, 읽거나 이해하는 대상의 대명사는 그 원형 바로 앞에 놓아요.',
    [['그 책을 읽고 싶다','Je veux le lire.'],['그 편지를 읽고 싶다','Je veux la lire.'],['그 편지를 이해할 수 있다','Je peux la comprendre.']],['Je veux lire le livre. → Je veux le lire.','나는 그 책을 읽고 싶어. → 나는 그것을 읽고 싶어.'],'Je le veux lire나 Je la peux comprendre가 아니에요. le·la는 lire·comprendre의 목적어예요.'),
  objectNegative:lesson('ne → 대명사 → 동사 → pas','대명사가 있는 부정문에서는 ne 뒤에 목적어 대명사를 놓고, 활용된 동사 뒤에 pas를 써요.',
    [['긍정','Je le lis.'],['부정','Je ne le lis pas.'],['복수 목적어','Je ne les lis pas.']],['Je ne la lis pas.','나는 그것을 읽지 않아. (그 편지를)'],'Je ne lis pas le라고 뒤로 보내지 않아요. 명사 앞의 관사 le와 목적어 대명사 le의 자리를 구분해요.'),
  objectElision:lesson('le·la + 모음 → l’','목적어 대명사 le와 la는 모음이나 무음 h 앞에서 l’로 줄어요. 복수 les는 줄이지 않아요.',
    [['le + aime','Je l’aime.'],['la + aime','Je l’aime.'],['les + aime','Je les aime.']],['J’aime ce livre. → Je l’aime.','나는 이 책을 좋아해. → 나는 그것을 좋아해.'],'Je le aime나 Je la aime라고 쓰지 않아요. l’aime의 l’와 aime 사이를 아포스트로피로 연결해요.'),
  yLocation:lesson('이미 나온 장소를 y로 받아요','y는 앞에서 말한 장소를 반복하지 않도록 해요. 활용된 동사 앞에 놓고, je는 y 앞에서 j’로 줄어요.',
    [['à Paris · 파리에','J’y vais.'],['à la maison · 집에','J’y suis.'],['그곳에서 일한다','Elle y travaille.']],['Elle travaille à Paris. → Elle y travaille.','그녀는 파리에서 일해. → 그녀는 그곳에서 일해.'],'장소를 대신한 y 뒤에 à Paris를 다시 붙이지 않아요. J’y와 동사 vais·suis는 따로 써요.'),
  yInfinitive:lesson('가고 싶은 곳: y aller','y가 aller의 목적지를 나타내면 동사원형 aller 바로 앞에 놓아요. veux가 아니라 aller와 연결된 말이에요.',
    [['파리에 가고 싶다','Je veux aller à Paris.'],['그곳에 가고 싶다','Je veux y aller.'],['그곳에 갈 수 있다','Je peux y aller.']],['Tu veux y aller.','너는 그곳에 가고 싶어.'],'이 뜻에서는 J’y veux aller가 아니에요. veux → y → aller 순서예요.'),
  enQuantity:lesson('en으로 명사를 받고 숫자는 남겨요','사과 몇 개처럼 수량을 말한 명사를 en으로 받을 수 있어요. “몇 개”인지는 en 뒤의 문장에 남겨요.',
    [['사과 두 개가 있다','J’ai deux pommes.'],['(사과가) 두 개 있다','J’en ai deux.'],['(사과가) 세 개 있다','J’en ai trois.'],['(사과가) 한 개 있다','J’en ai une.']],['J’ai trois pommes. → J’en ai trois.','사과 세 개가 있어. → 세 개 있어. (앞서 말한 사과)'],'en을 써도 deux·trois는 지우지 않아요. 하나일 때의 un·une는 대신한 명사의 성에 맞춰요.'),
  enNegative:lesson('하나도 없다: Je n’en ai pas','en 앞에서 ne가 n’로 줄어요. 숫자 없이 “하나도 없다”라고 할 때 Je n’en ai pas를 써요.',
    [['두 개 있다','J’en ai deux.'],['하나도 없다','Je n’en ai pas.'],['순서','Je → n’en → ai → pas']],['Tu n’en as pas.','넌 하나도 없어. (앞서 말한 사과)'],'en은 ai 앞에 놓아요. J’en n’ai pas가 아니라 Je n’en ai pas예요.'),
  enPartitive:lesson('du thé도 en으로 받을 수 있어요','차를 얼마나 마시는지 밝히지 않을 때는 Je bois du thé라고 해요. 이미 차 이야기를 하고 있다면 du thé를 en으로 받아 J’en bois라고 할 수 있어요.',
    [['차를 마신다','Je bois du thé.'],['앞서 말한 차를 받기','J’en bois.'],['커피를 받기','Je bois du café. → J’en bois.']],['Tu bois du thé ? — Oui, j’en bois.','차 마셔? — 응, 마셔.'],'le thé처럼 특정한 차를 다시 가리킬 때는 le예요. du thé처럼 양을 정하지 않은 차를 가리킬 때는 en을 써요.'),
  relativeQui:lesson('관계절의 주어 역할은 qui','앞의 명사를 설명하는 절에서 행동하는 주체가 비어 있으면 qui를 써요. 사람과 사물 모두에 쓸 수 있어요.',
    [['일하는 친구','un ami qui travaille'],['프랑스어를 하는 친구','un ami qui parle français'],['리옹에 사는 친구','un ami qui habite à Lyon']],['J’ai un ami qui travaille ici.','나는 여기서 일하는 친구 한 명이 있어.'],'qui 뒤에 il 같은 주어를 다시 넣지 않아요. un ami qui il travaille라고 하지 않아요.'),
  relativeQue:lesson('관계절의 목적어 역할은 que','설명하는 절에 주어가 이미 있고 “무엇을?”이 비어 있으면 que를 써요. 앞의 명사가 그 목적어를 채워요.',
    [['내가 그 책을 읽는다','Je lis le livre.'],['내가 읽는 책','le livre que je lis'],['내가 좋아하는 카페','le café que j’aime']],['C’est le livre que je lis.','이건 내가 읽고 있는 책이야.'],'사람인지 사물인지로 qui·que를 고르지 않아요. 여기서는 읽는 주어 je가 이미 있으므로 que예요.'),
  relativeElision:lesson('que + elle → qu’elle','관계대명사 que는 모음 앞에서 qu’로 줄어요. elle는 읽는 사람, 앞의 livre는 읽는 대상이에요.',
    [['주어가 je','le livre que je lis'],['주어가 elle','le livre qu’elle lit'],['주어가 il','le livre qu’il lit']],['C’est le livre qu’elle lit.','이건 그녀가 읽고 있는 책이야.'],'qui를 줄인 형태가 아니에요. 목적어 역할의 que가 모음 앞에서 qu’가 된 거예요.'),
  quiNoElision:lesson('qui는 모음 앞에서도 그대로','qui가 관계절의 주어이면 다음 동사가 모음으로 시작해도 i를 줄이지 않아요.',
    [['문을 여는 열쇠','la clé qui ouvre la porte'],['여기 사는 친구','un ami qui habite ici'],['비교 · 목적어 que','le livre qu’elle lit']],['C’est la clé qui ouvre la porte.','이건 문을 여는 열쇠야.'],'열쇠가 문을 여는 주체이므로 qui예요. qu’ouvre가 아니라 qui ouvre로 써요.'),
  meilleur:lesson('bon의 비교급: meilleur','좋은 물건의 맛·질 등을 비교할 때 bon 대신 meilleur를 써요. 설명하는 명사의 성·수에 맞춰 끝을 바꿔요.',
    [['남성 단수','meilleur'],['여성 단수','meilleure'],['남성 복수','meilleurs'],['여성 복수','meilleures']],['Cette soupe est meilleure.','이 수프가 더 맛있어.'],'보통 “더 좋은”은 plus bon이 아니라 meilleur예요. 여성 soupe에는 meilleure, 복수 livres에는 meilleurs예요.'),
  mieux:lesson('행동을 더 잘한다면 mieux','bien은 “잘”, 그 비교급 mieux는 “더 잘”이에요. 말하기·이해하기 같은 동작을 꾸미며 성·수에 따라 바뀌지 않아요.',
    [['프랑스어를 잘한다','Elle parle bien français.'],['프랑스어를 더 잘한다','Elle parle mieux français.'],['전보다 더 잘 이해한다','Je comprends mieux qu’avant.']],['Elle parle mieux français que moi.','그녀는 나보다 프랑스어를 더 잘해.'],'여성 주어라고 meilleure로 바꾸지 않아요. 물건의 질은 meilleur, 행동을 더 잘하는 것은 mieux예요.'),
  celleLa:lesson('celle-là는 여성 명사를 받아요','방 chambre는 여성 명사예요. “저 방”을 반복하지 않고 celle-là로 받으며 plus … que로 비교해요.',
    [['남성 명사 · 저 가방','celui-là'],['여성 명사 · 저 방','celle-là'],['더 조용하다','plus calme que celle-là']],['Cette chambre est plus calme que celle-là.','이 방은 저 방보다 더 조용해.'],'calme는 남성·여성 단수형이 같아요. celle-là는 비교 대상인 chambre의 성에 맞춘 말이에요.'),
  parceQue:lesson('이유를 붙이는 parce que','parce que는 “~이기 때문에”예요. 먼저 한 행동을 말하고 뒤에 이유를 붙일 수 있어요.',
    [['비가 오기 때문에','parce qu’il pleut'],['시간이 없기 때문에','parce que je n’ai pas le temps'],['이유를 먼저 써도 돼요','Parce qu’il pleut, je reste à la maison.']],['Je reste à la maison parce qu’il pleut.','비가 와서 집에 머물러.'],'il 앞에서는 parce qu’il, je 앞에서는 parce que je예요. 발음해 보면 il 앞에서는 que의 마지막 모음이 들리지 않아요.'),
  donc:lesson('원인 다음의 결과를 donc로','donc는 “그래서”예요. 앞에 이유나 상황을 말하고 뒤에 그 결과를 이어줘요.',
    [['원인','Il pleut.'],['결과','Je reste à la maison.'],['하나로 연결','Il pleut, donc je reste à la maison.']],['Je n’ai pas le temps, donc je ne peux pas venir.','나는 시간이 없어. 그래서 갈 수 없어.'],'parce que는 이유를, donc는 결과를 이어요. 두 연결어를 바꾸려면 문장 관계도 다시 봐야 해요.'),
  pourtant:lesson('예상과 다른 결과는 pourtant','pourtant는 “그런데도”예요. 비가 오는데 외출하거나 비싼데도 사고 싶은 것처럼 예상과 다른 내용을 이어줘요.',
    [['상황','Il pleut.'],['예상과 다른 행동','Pourtant, je sors.'],['비싸지만 사고 싶다','C’est cher, pourtant je veux l’acheter.']],['Il pleut, pourtant je sors.','비가 와. 그런데도 나는 외출해.'],'donc는 자연스러운 결과, pourtant는 대조예요. l’acheter의 l’는 사려는 것을 받는 목적어예요.'),
  penseQue:lesson('Je pense que 뒤에 생각을 붙여요','긍정형 Je pense que는 “나는 ~라고 생각한다”예요. 이 문장에서는 판단 내용을 직설법으로 표현해요.',
    [['중요하다고 생각한다','Je pense que c’est important.'],['그가 옳다고 생각한다','Je pense qu’il a raison.'],['그녀가 온다고 생각한다','Je pense qu’elle vient.']],['Je pense que c’est important.','나는 이게 중요하다고 생각해.'],'que는 il·elle 앞에서 qu’로 줄어요. 부정·의문형 penser의 법 선택은 문맥에 따라 달라질 수 있어요.'),
  avoirRaison:lesson('옳다: avoir raison','“말이 맞다, 옳다”는 avoir raison으로 표현해요. avoir를 주어에 맞춰 ai·as·a로 바꿔요.',
    [['내가 옳다','J’ai raison.'],['네가 옳다','Tu as raison.'],['그가 옳다','Il a raison.']],['Je pense qu’il a raison.','나는 그가 옳다고 생각해.'],'Il est raison이 아니에요. 긍정형 Je pense que 뒤에서는 여기의 직설법 a를 써요.'),
  apprendreReason:lesson('parce que로 연습하는 이유를 말해요','‘나는 연습해’는 je m’entraîne, ‘나는 프랑스어를 배워’는 j’apprends le français예요. parce que로 이으면 왜 연습하는지 설명할 수 있어요.',
    [['나는 배운다','j’apprends'],['너는 배운다','tu apprends'],['그녀는 배운다','elle apprend'],['프랑스어를 배우다','apprendre le français']],['Je m’entraîne tous les jours parce que j’apprends le français.','프랑스어를 배우고 있어서 매일 연습해.'],'apprends의 마지막 s를 확인해요. 배우는 언어에는 여기서 le français, 매일은 tous les jours예요.'),
  subjVenir:lesson('venir의 접속법: vienne·viennes','필요를 말하는 Il faut que나 바람을 말하는 Je veux que 뒤에서는 venir를 접속법으로 써요.',
    [['que je','vienne'],['que tu','viennes'],['qu’il / qu’elle','vienne'],['que nous','venions'],['que vous','veniez'],['qu’ils / qu’elles','viennent']],['Il faut que tu viennes.','네가 와야 해.'],'현재 직설법 tu viens와 접속법 que tu viennes는 달라요. tu형은 viennes, il형은 vienne예요.'),
  subjEtre:lesson('être의 접속법: sois·soit','Il faut que 뒤에서 필요한 상태를 표현하면 être의 접속법을 써요. 형태가 불규칙하므로 주어와 함께 익혀요.',
    [['que je','sois'],['que tu','sois'],['qu’il / qu’elle','soit'],['que nous','soyons'],['que vous','soyez'],['qu’ils / qu’elles','soient']],['Il faut qu’elle soit prête.','그녀가 준비되어 있어야 해.'],'Il faut que tu es가 아니라 tu sois예요. prête의 e는 여성 주어 elle에 맞춘 형용사 표시예요.'),
  subjFaire:lesson('faire의 접속법은 fass-','faire의 현재 직설법 tu fais와 달리, 접속법은 fass-를 사용해요. tu에는 -es를 붙여 fasses예요.',
    [['que je','fasse'],['que tu','fasses'],['qu’il / qu’elle','fasse'],['que nous','fassions'],['que vous','fassiez'],['qu’ils / qu’elles','fassent']],['Il faut que tu fasses ce travail.','네가 이 일을 해야 해.'],'fasses에는 s가 세 개예요: 어간 fass-의 두 개와 어미 -es의 한 개예요.'),
  subjPartir:lesson('partir의 nous 접속법: partions','Il faut que nous 뒤에서는 partir의 접속법 partions를 써요. nous의 접속법 어미는 -ions예요.',
    [['que je','parte'],['que tu','partes'],['qu’il / qu’elle','parte'],['que nous','partions'],['que vous','partiez'],['qu’ils / qu’elles','partent']],['Il faut que nous partions.','우리가 떠나야 해.'],'partions는 반과거와 모양이 같아요. 여기서는 Il faut que가 이끄는 절이므로 접속법 현재예요.'),
  subjAvoir:lesson('avoir의 접속법: aie·aies·ait','다른 사람이 어떤 상태이기를 바라는 Je veux que 뒤에서는 avoir를 접속법으로 써요.',
    [['que j’','aie'],['que tu','aies'],['qu’il / qu’elle','ait'],['que nous','ayons'],['que vous','ayez'],['qu’ils / qu’elles','aient']],['Je veux que tu aies du temps.','나는 네가 시간이 있기를 바라.'],'tu as는 직설법, que tu aies는 접속법이에요. aies와 ais를 혼동하지 않아요.')
});

// Each stem is authored; the tables show all persons without unrelated tenses.
function formsForStem(stem,endings) {
  const firstPerson = /^[aeiouéèê]/.test(stem) ? 'j’' : 'je';
  const subjects = [firstPerson,'tu','il / elle','nous','vous','ils / elles'];
  return endings.map((ending,index)=>[subjects[index],stem+ending]);
}
const future=(verb,stem,example,caution)=>lesson(verb+'의 단순미래: '+stem+'-',
  '단순미래는 '+verb+'의 미래 어간 '+stem+'-에 주어별 어미 -ai, -as, -a, -ons, -ez, -ont를 붙여요.',
  formsForStem(stem,['ai','as','a','ons','ez','ont']),example,caution);
Object.assign(miniLessons,{
  futureTravailler:future('travailler','travailler',['Demain, je travaillerai.','나는 내일 일할 거야.'],'je의 미래형은 travaillerai예요. 끝에 s가 붙은 travaillerais는 조건법 현재예요.'),
  futureManger:future('manger','manger',['Demain, nous mangerons.','우리는 내일 먹을 거야.'],'현재형 nous mangeons와 미래형 nous mangerons를 비교해요. 미래에는 원형의 r이 남아요.'),
  futureAvoir:future('avoir','aur',['Tu auras du temps demain.','너는 내일 시간이 있을 거야.'],'avoir는 불규칙 미래 어간 aur-를 써요. avoirai가 아니라 aurai예요.'),
  futureAller:future('aller','ir',['J’irai à Paris demain.','나는 내일 파리에 갈 거야.'],'aller의 미래 어간은 ir-예요. j’irai의 끝은 -ai이고, j’irais는 조건법이에요.'),
  futureEtre:future('être','ser',['Elle sera ici demain.','그녀는 내일 여기에 있을 거야.'],'être의 미래 어간은 ser-예요. elle에는 sera, je에는 serai를 써요.'),
  futureVenir:future('venir','viendr',['Vous viendrez demain.','내일 오실 거예요.'],'현재형 vous venez와 미래형 vous viendrez는 어간이 달라요. 미래의 d와 r을 확인해요.'),
  futureFaire:future('faire','fer',['Nous ferons ce travail demain.','우리는 내일 이 일을 할 거야.'],'faire의 미래 어간은 fer-예요. nous의 미래는 ferons이고 현재는 faisons예요.'),
  futureRester:future('rester','rester',['S’il pleut, nous resterons à la maison.','비가 오면 우리는 집에 있을 거야.'],'조건의 pleut는 현재형, 결과의 resterons는 미래형이에요. rester + -ons로 만들어요.'),
  futureParler:future('parler','parler',['Si tu as le temps, nous parlerons.','네가 시간이 있으면 우리는 이야기할 거야.'],'조건절 Si tu as는 현재형이에요. 결과절의 nous에는 미래 어미 -ons를 써요.')
});
const conditional=(verb,stem,example,caution)=>lesson(verb+'의 조건법: '+stem+'- + 반과거 어미',
  '가정의 결과를 표현하는 조건법 현재는 미래 어간 '+stem+'-에 -ais, -ais, -ait, -ions, -iez, -aient를 붙여요.',
  formsForStem(stem,['ais','ais','ait','ions','iez','aient']),example,caution);
